/**
 * The street worker's SDF atlas: every painted shape that is not a straight
 * line — turn arrows, lane words, street names — is a quad sampling ONE
 * single-channel signed-distance texture, so a tile's markings are one draw
 * call and stay sharp at any zoom (`docs/MAP_STREETS.md` → "Arrows, words and
 * names").
 *
 * - **Glyphs are the map's own**: the SDF bitmaps of the style's glyph
 *   ranges (`/map/fonts/{fontstack}/{range}.pbf`, Inter, generated by
 *   `scripts/build-map-glyphs.ts`), decoded with the same `glyph-pbf.ts` the
 *   build uses. MapLibre's encoding is kept as is: 24 px em, a 3 px border,
 *   the edge at byte 191 (radius 8, cutoff 0.25).
 * - **Arrows are drawn here**, as the union of stroked paths and heads, into
 *   the same encoding, once per shape.
 *
 * The worker owns the atlas (one worker, so one packing order); the renderer
 * mirrors it from the patches each reply carries (`takePatches`). Shelf
 * packing, never repacked: a full atlas refuses further shapes, and what
 * would have used them is not drawn (counted in the stats).
 */
import { GLYPH_PBF_BORDER, type MapGlyph } from '@/scripts/mapgen/glyph-pbf';

import type { ArrowPart } from './markings';

export const ATLAS_SIZE = 1024;
/** The SDF encoding (MapLibre's): value 191 on the edge, 8 px of range. */
export const SDF_EDGE = 191 / 255;
const SDF_RADIUS = 8;
const SDF_CUTOFF = 0.25;

/** An arrow's cell, px: the shape is drawn in x ∈ [−16, 16], y ∈ [0, 80], pointing +y. */
export const ARROW_CELL = { width: 48, height: 96, pad: 8, shapeHalfWidth: 16, shapeLength: 80 };

export interface AtlasRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface AtlasPatch extends AtlasRect {
  data: Uint8Array;
}

export interface AtlasGlyph {
  /** `null` for whitespace (no bitmap). */
  rect: AtlasRect | null;
  metrics: MapGlyph;
}

/** Signed distance (px, negative inside) from `p` to a capsule a–b of radius `r`. */
function capsule(px: number, py: number, a: [number, number], b: [number, number], r: number) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const len2 = dx * dx + dy * dy;
  const t = len2 > 0 ? Math.max(0, Math.min(1, ((px - a[0]) * dx + (py - a[1]) * dy) / len2)) : 0;
  return Math.hypot(px - (a[0] + dx * t), py - (a[1] + dy * t)) - r;
}

/** Signed distance to a triangle (Inigo Quilez's formulation). */
function triangle(px: number, py: number, t: readonly [number, number][]) {
  let d = Number.POSITIVE_INFINITY;
  let sign = 0;
  for (let i = 0; i < 3; i++) {
    const [ax, ay] = t[i];
    const [bx, by] = t[(i + 1) % 3];
    const ex = bx - ax;
    const ey = by - ay;
    const wx = px - ax;
    const wy = py - ay;
    const k = Math.max(0, Math.min(1, (wx * ex + wy * ey) / (ex * ex + ey * ey)));
    d = Math.min(d, Math.hypot(wx - ex * k, wy - ey * k));
    sign += Math.sign(ex * wy - ey * wx);
  }
  return Math.abs(sign) === 3 ? -d : d;
}

interface Stroke {
  path: [number, number][];
  /** Head: tip and the direction it points (unit). */
  tip: [number, number];
  dir: [number, number];
}

const SHAFT = 2.6;
const HEAD_LENGTH = 20;
const HEAD_HALF = 10;

/** Each part as a stroke from the common base, in the cell's shape space. */
function strokes(part: ArrowPart): Stroke {
  const up: [number, number] = [0, 1];
  switch (part) {
    case 'through':
      return {
        path: [
          [0, 0],
          [0, 62],
        ],
        tip: [0, 80],
        dir: up,
      };
    case 'left':
      return {
        path: [
          [0, 0],
          [0, 42],
          [-2, 49],
          [-6, 52],
        ],
        tip: [-16, 53],
        dir: [-1, 0],
      };
    case 'right':
      return {
        path: [
          [0, 0],
          [0, 42],
          [2, 49],
          [6, 52],
        ],
        tip: [16, 53],
        dir: [1, 0],
      };
    case 'slight_left':
      return {
        path: [
          [0, 0],
          [0, 36],
          [-5, 52],
        ],
        tip: [-11, 72],
        dir: norm(-0.42, 1),
      };
    case 'slight_right':
      return {
        path: [
          [0, 0],
          [0, 36],
          [5, 52],
        ],
        tip: [11, 72],
        dir: norm(0.42, 1),
      };
    case 'reverse':
      return {
        path: [
          [4, 0],
          [4, 58],
          [0, 66],
          [-6, 66],
          [-10, 58],
          [-10, 44],
        ],
        tip: [-10, 26],
        dir: [0, -1],
      };
    case 'merge_to_left':
      return {
        path: [
          [6, 0],
          [6, 20],
          [-4, 52],
        ],
        tip: [-9, 72],
        dir: norm(-0.3, 1),
      };
    case 'merge_to_right':
      return {
        path: [
          [-6, 0],
          [-6, 20],
          [4, 52],
        ],
        tip: [9, 72],
        dir: norm(0.3, 1),
      };
  }
}

function norm(x: number, y: number): [number, number] {
  const l = Math.hypot(x, y);
  return [x / l, y / l];
}

/** Rasterise an arrow's SDF into a cell-sized byte array (row 0 at the top = the arrow's tip end). */
export function rasterArrow(parts: readonly ArrowPart[], mirror = false): Uint8Array {
  const { width, height, pad } = ARROW_CELL;
  const shapes = parts.map(strokes).map((s) => {
    const f = (p: [number, number]): [number, number] => (mirror ? [-p[0], p[1]] : p);
    const tip = f(s.tip);
    const dir = f(s.dir);
    const base: [number, number] = [tip[0] - dir[0] * HEAD_LENGTH, tip[1] - dir[1] * HEAD_LENGTH];
    const side: [number, number] = [-dir[1] * HEAD_HALF, dir[0] * HEAD_HALF];
    return {
      path: s.path.map(f),
      head: [
        tip,
        [base[0] + side[0], base[1] + side[1]],
        [base[0] - side[0], base[1] - side[1]],
      ] as [number, number][],
      neck: base,
    };
  });
  const out = new Uint8Array(width * height);
  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      const x = i + 0.5 - width / 2;
      const y = height - pad - (j + 0.5);
      let d = Number.POSITIVE_INFINITY;
      for (const shape of shapes) {
        const path = [...shape.path, shape.neck];
        for (let k = 0; k + 1 < path.length; k++) {
          d = Math.min(d, capsule(x, y, path[k], path[k + 1], SHAFT));
        }
        d = Math.min(d, triangle(x, y, shape.head));
      }
      const v = 1 - (d / SDF_RADIUS + SDF_CUTOFF);
      out[j * width + i] = Math.round(Math.max(0, Math.min(1, v)) * 255);
    }
  }
  return out;
}

export class StreetAtlas {
  readonly size = ATLAS_SIZE;
  private shelfX = 0;
  private shelfY = 0;
  private shelfH = 0;
  private patches: AtlasPatch[] = [];
  private arrows = new Map<string, AtlasRect | null>();
  private loaded = new Map<number, MapGlyph>();
  private placed = new Map<number, AtlasRect | null>();
  /** Shapes refused because the atlas is full. */
  refused = 0;

  /** A free rectangle, or `null` when the atlas is full. */
  private allocate(w: number, h: number): AtlasRect | null {
    const gap = 1;
    if (this.shelfX + w > this.size) {
      this.shelfY += this.shelfH + gap;
      this.shelfX = 0;
      this.shelfH = 0;
    }
    if (this.shelfY + h > this.size || w > this.size) {
      this.refused++;
      return null;
    }
    const rect = { x: this.shelfX, y: this.shelfY, w, h };
    this.shelfX += w + gap;
    this.shelfH = Math.max(this.shelfH, h);
    return rect;
  }

  private put(rect: AtlasRect, data: Uint8Array) {
    this.patches.push({ ...rect, data });
  }

  /** An arrow shape's rectangle, rasterised on first use. */
  arrow(key: string, parts: readonly ArrowPart[]): AtlasRect | null {
    const known = this.arrows.get(key);
    if (known !== undefined) return known;
    const rect = this.allocate(ARROW_CELL.width, ARROW_CELL.height);
    if (rect) this.put(rect, rasterArrow(parts, key.endsWith('@lht')));
    this.arrows.set(key, rect);
    return rect;
  }

  /** Make a range's glyphs available (placed in the atlas on first use). */
  addGlyphs(glyphs: readonly MapGlyph[]): void {
    for (const glyph of glyphs) this.loaded.set(glyph.id, glyph);
  }

  /** A code point's glyph, or `undefined` when no loaded range has it. */
  glyph(code: number): AtlasGlyph | undefined {
    const metrics = this.loaded.get(code);
    if (!metrics) return undefined;
    let rect = this.placed.get(code);
    if (rect === undefined) {
      if (!metrics.bitmap || metrics.width === 0) rect = null;
      else {
        const w = metrics.width + 2 * GLYPH_PBF_BORDER;
        const h = metrics.height + 2 * GLYPH_PBF_BORDER;
        rect = this.allocate(w, h);
        if (rect) this.put(rect, metrics.bitmap);
        else return undefined;
      }
      this.placed.set(code, rect);
    }
    return { rect, metrics };
  }

  /** The bytes placed since the last call, for the renderer's copy. */
  takePatches(): AtlasPatch[] {
    const out = this.patches;
    this.patches = [];
    return out;
  }
}
